// GIVEN by the paper — do not change.
public class Laptop {
    private final String maker;
    private final int rate;

    public Laptop(String maker, int rate) {
        this.maker = maker;
        this.rate = rate;
    }

    public String getMaker() {
        return maker;
    }

    public int getRate() {
        return rate;
    }

