   "h": "eyJuYW1lIjoiVEMzIHJlbW92ZSBBIG1ha2VycyIsImlucHV0IjoiNFxuQXN1czs1XG5EZWxsOzhcbmFwcGxlOzFcbk1TSTs2XG4zXG4iLCJleHBlY3RlZCI6IkVudGVyIFRDICgxLCAyIG9yIDMpOiBcbk9VVFBVVDpcblsoRGVsbCwgOCksIChNU0ksIDYpXSAob3JpZ2luYWwgc3RpbGwgNClcbiJ9"
  },
  {
   "h": "eyJuYW1lIjoiVEMxIGFsbCBlcXVhbCwgVEMzIGFsbCByZW1vdmVkIiwiaW5wdXQiOiIyXG5BOzRcbmE7NFxuMVxuIiwiZXhwZWN0ZWQiOiJFbnRlciBUQyAoMSwgMiBvciAzKTogXG5PVVRQVVQ6XG4wXG4ifQ=="
  }
 ]
};

const HERE = path.dirname(fileURLToPath(import.meta.url));
const args = process.argv.slice(2);
const SHOW = args.includes('--show');
const RECORD = args.includes('--record') ? args[args.indexOf('--record') + 1] : null;
const ONLY = args.includes('--case') ? Number(args[args.indexOf('--case') + 1]) : null;
const WIN = process.platform === 'win32';
const color = process.stdout.isTTY && !process.env.NO_COLOR;
const paint = (c, s) => (color ? `\x1b[${c}m${s}\x1b[0m` : s);
